mapper.select:
SELECT v.`id`, v.`shop_id`, v.`title`, v.`sub_title`, v.`rules`, v.`pay_value`, v.`actual_value`, v.`type`, v.`status`, sv.`stock`, sv.`begin_time`, sv.`end_time`, v.`create_time`, v.`update_time` FROM tb_voucher v INNER JOIN tb_shop s ON s.id = v.shop_id LEFT JOIN tb_seckill_voucher sv ON v.id = sv.voucher_id WHERE v.shop_id = #{shopId}
AND s.merchant_id = #{merchantId}
ORDER BY v.id DESC
